\)

class SignUpViewModel\(
    private val authRepository: AuthRepository
\) : ViewModel\(\) {

    private val _uiState = MutableStateFlow\(SignUpUiState\(\)\)
    val uiState: StateFlow<SignUpUiState> = _uiState.asStateFlow\(\)

